<section id="staff"><h2>Staff accounts</h2>
<?php if($can('users.manage')):?><details class="card"><summary>Create staff account</summary><form method="post"><label for="new-name">Full name</label><input id="new-name" name="name" maxlength="120" required><label for="new-email">Email</label><input id="new-email" name="email" type="email" maxlength="190" required><label for="temporary-password">Temporary password</label><div class="password"><input id="temporary-password" name="password" type="password" minlength="12" maxlength="72" autocomplete="new-password" required><button type="button" class="secondary" data-password-toggle="temporary-password" aria-pressed="false" aria-label="Show password">Show</button></div><small>The new account starts with the clerk role and must change its password at first sign-in. Share the temporary password privately.</small><?php access_management_fields('save_user')?><p><button>Create account</button></p></form></details><?php endif?>
<?php foreach($users as $staff):?><details class="card"><summary><?=access_h($staff['name'])?> · <?=access_h($staff['email'])?> · <?=$staff['active']?'Active':'Inactive'?></summary><p>Staff #<?=(int)$staff['id']?> · Legacy role: <?=access_h($staff['role'])?><?=$staff['must_change_password']?' · Password change required':''?></p><div class="grid">
<?php if($can('users.manage')):?><form method="post"><h2>Profile</h2><label for="name-<?=(int)$staff['id']?>">Name</label><input id="name-<?=(int)$staff['id']?>" name="name" value="<?=access_h($staff['name'])?>" maxlength="120" required><label for="email-<?=(int)$staff['id']?>">Email</label><input id="email-<?=(int)$staff['id']?>" name="email" type="email" value="<?=access_h($staff['email'])?>" maxlength="190" required><?php access_management_fields('save_user',(int)$staff['id'])?><p><button>Save profile</button></p></form>
<form method="post"><h2>Account state</h2><input type="hidden" name="active" value="<?=$staff['active']?'0':'1'?>"><p>Deactivation retains historical attribution and prevents sign-in. The last active administrator is protected.</p><?php access_management_fields('set_active',(int)$staff['id'])?><p><button><?=$staff['active']?'Deactivate':'Reactivate'?></button></p></form>
<form method="post"><h2>Revoke sessions</h2><p>Sign this account out on its next request.</p><?php access_management_fields('revoke_sessions',(int)$staff['id'])?><p><button>Revoke sessions</button></p></form><?php endif?>
<?php if($can('roles.assign')):?><form method="post" class="checks"><h2>Assigned roles</h2><?php foreach($roles as $role):?><label><input type="checkbox" name="ids[]" value="<?=(int)$role['id']?>" <?=in_array((int)$role['id'],$userRoles[$staff['id']] ?? [],true)?'checked':''?>><?=access_h($role['name'])?></label><?php endforeach?><?php access_management_fields('assign_roles',(int)$staff['id'])?><p><button>Save roles</button></p></form><?php endif?>
</div></details><?php endforeach?></section>
<section id="roles"><h2>Roles</h2>
<?php if($can('roles.manage')):?><details class="card"><summary>Create role</summary><form method="post"><label for="role-code">Role code</label><input id="role-code" name="code" pattern="[a-z][a-z0-9_.\-]{2,59}" maxlength="60" required><label for="role-description">Description</label><input id="role-description" name="description" maxlength="255" required><?php access_management_fields('create_role')?><p><button>Create role</button></p></form></details><?php endif?>
<?php foreach($roles as $role):?><details class="card"><summary><?=access_h($role['name'])?></summary><p><?=access_h($role['description'])?></p><?php if($role['name']==='admin'):?><p>The administrator role retains all built-in privileges.</p><?php elseif($can('roles.manage')):?><form method="post" class="checks"><h2>Assigned privileges</h2><?php foreach($privileges as $privilege):?><label><input type="checkbox" name="ids[]" value="<?=(int)$privilege['id']?>" <?=in_array((int)$privilege['id'],$rolePrivileges[$role['id']] ?? [],true)?'checked':''?>><?=access_h($privilege['code'])?> · <?=access_h($privilege['description'])?></label><?php endforeach?><?php access_management_fields('assign_privileges',(int)$role['id'])?><p><button>Save privileges</button></p></form><?php endif?></details><?php endforeach?></section>
<section id="privileges"><h2>Privilege catalogue</h2><p>Built-in privileges protect application endpoints. Custom privileges can be assigned now; a new feature must explicitly check its custom privilege before it grants access.</p>
<?php if($can('privileges.manage')):?><details class="card"><summary>Create custom privilege</summary><form method="post"><label for="privilege-code">Code, starting with custom.</label><input id="privilege-code" name="code" placeholder="custom.example.view" maxlength="60" required><label for="privilege-description">Description</label><input id="privilege-description" name="description" maxlength="255" required><?php access_management_fields('create_privilege')?><p><button>Create privilege</button></p></form></details><?php endif?>
<div class="card scroll"><table><thead><tr><th>Code</th><th>Description</th></tr></thead><tbody><?php foreach($privileges as $privilege):?><tr><td><?=access_h($privilege['code'])?></td><td><?=access_h($privilege['description'])?></td></tr><?php endforeach?></tbody></table></div></section><?php require dirname(__DIR__).'/layouts/end.php'; ?>